import{_ as r,C as i,c as l,o as g,a3 as n,G as s,j as a,a as t}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Packages","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/tracking/packages.md","filePath":"master/supply-chain/inventories/tracking/packages.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/inventories/tracking/packages.md"};function p(h,e,d,k,u,m){const o=i("ImagePopup");return g(),l("div",null,[e[0]||(e[0]=n('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h1><p>A package is a physical container that holds products, such as a box, a pallet or a parcel. You track it by name, so you can move or ship the whole thing and know what sits inside. A package type is the template: its size and weight limits.</p><blockquote><p><strong>In simple words:</strong> A package type is the kind of box. A package is one real box with a name.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Go to <code>Inventory → Settings → Manage Operations</code> and turn on <strong>Packages</strong>. Click <strong>Save changes</strong>. This reveals <code>Inventory → Products → Packages</code> and <code>Inventory → Configurations → Delivery → Package Types</code>.</p>',5)),s(o,{src:"/images1/inventory/pkg_setting_on.png",alt:"Manage Operations with the Packages option switched on"}),e[1]||(e[1]=n('<h2 id="create-a-package-type" tabindex="-1">Create a package type <a class="header-anchor" href="#create-a-package-type" aria-label="Permalink to &quot;Create a package type&quot;">​</a></h2><ol><li>Go to <code>Inventory → Configurations → Delivery → Package Types</code>.</li><li>Click <strong>New Package Type</strong>. The list shows the columns <strong>Name</strong>, <strong>Height</strong>, <strong>Width</strong> and <strong>Length</strong>.</li></ol>',2)),s(o,{src:"/images1/inventory/pkg_type_create.png",alt:"Package type form named Small Box with size and weight values"}),e[2]||(e[2]=n('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> Required. For example <strong>Small Box</strong>.</li><li><strong>Barcode:</strong> Scan code of the type.</li><li><strong>Company:</strong> Owner company.</li></ul><h3 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h3><ul><li><strong><em>Length*, Width*, Height*:</em></strong> The inner size. Default 0.</li></ul><h3 id="weight" tabindex="-1">Weight <a class="header-anchor" href="#weight" aria-label="Permalink to &quot;Weight&quot;">​</a></h3><ul><li><strong><em>Weight:</em></strong> Required. Weight of the empty box.</li><li><strong><em>Max Weight:</em></strong> Required. The most it can carry.</li></ul><ol start="3"><li>Click <strong>Create</strong>.</li></ol><h2 id="create-a-package" tabindex="-1">Create a package <a class="header-anchor" href="#create-a-package" aria-label="Permalink to &quot;Create a package&quot;">​</a></h2><ol><li>Go to <code>Inventory → Products → Packages</code> and click <strong>New Package</strong>.</li></ol>',9)),s(o,{src:"/images1/inventory/pkg_create.png",alt:"Create package form with name PACK007, type Small Box, pack date and location WH/Stock"}),e[3]||(e[3]=n('<ul><li><strong><em>Name:</em></strong> Required. Package code. The field placeholder reads <strong>eg. PACK007</strong>.</li><li><strong><em>Package Type:</em></strong> Pick a type such as <strong>Small Box</strong>. Click <strong>+</strong> next to it to create a type on the spot.</li><li><strong><em>Pack Date:</em></strong> The date it was packed. It defaults to today.</li><li><strong><em>Location:</em></strong> Where the package sits, such as <strong>WH/Stock</strong>.</li></ul><ol start="2"><li>Click <strong>Create</strong>.</li></ol><p>The list opens on the <strong>Internal Locations</strong> tab. The other tab is <strong>Default</strong>. It shows <strong>Name</strong>, <strong>Package Type</strong>, <strong>Location</strong> and <strong>Company</strong>. Group by <strong>Package Type</strong> or <strong>Location</strong>. A package in use cannot be deleted. <strong>Delete</strong> is in the three-dot menu at the end of each row.</p>',3)),s(o,{src:"/images1/inventory/pkg_list.png",alt:"Packages list with PACK007 and its type and location"}),e[4]||(e[4]=a("h2",{id:"put-stock-in-a-package",tabindex:"-1"},[t("Put stock in a package "),a("a",{class:"header-anchor",href:"#put-stock-in-a-package","aria-label":'Permalink to "Put stock in a package"'},"​")],-1)),e[5]||(e[5]=a("p",null,[t("A package must exist before you can pick it. Create it first, as shown above. On a receipt or other transfer, click the small list icon next to "),a("strong",null,"Quantity"),t(" on the product row. Its tooltip reads "),a("strong",null,"Manage Stock Moves"),t(". Each line has "),a("strong",null,"Destination Package"),t(", a searchable select. It lists existing packages only. Choose the package that receives that quantity, then click "),a("strong",null,"Save"),t(".")],-1)),s(o,{src:"/images1/inventory/pkg_destination_package.png",alt:"Manage Stock Moves window with Destination Package PACK010 on a line"}),e[6]||(e[6]=n('<p>After validation, the <strong>Quantities</strong> tab and the <strong>Locations</strong> report show the <strong>Package</strong> column. You can also add a quantity directly with a package. See <a href="./../products/configure-product.html">Configure a product</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A package cannot move into itself. If you see &quot;Can not move same package content&quot;, pick a different package.</p></div><h2 id="print-package-labels" tabindex="-1">Print package labels <a class="header-anchor" href="#print-package-labels" aria-label="Permalink to &quot;Print package labels&quot;">​</a></h2><p>Tick one or more packages in the list. Choose a bulk action.</p><ul><li><strong>Print Barcode:</strong> Prints the package name as a barcode.</li><li><strong>Print Barcode With Content:</strong> Also prints what sits inside.</li></ul><p>On a transfer, the <strong>Print</strong> menu has <strong>Packages</strong>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>A package is a label on stock, like a lot, but it also has a place. When you move a package, everything in it moves with it. Reports can group by <strong>Package</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../products/attributes-and-packagings.html">Attributes and packagings</a></li><li><a href="./../operations/print-documents.html">Print documents</a></li><li><a href="./../reporting/stock-report.html">Stock report</a></li></ul>',10))])}const b=r(c,[["render",p]]);export{P as __pageData,b as default};
